mapper.update:
UPDATE PARKING_USAGE
   SET PARKING_RESERVATION_ID = CASE WHEN PARKING_SPACE_ID = #{spaceId}
                                    THEN PARKING_RESERVATION_ID ELSE NULL END,
       PARKING_SPACE_ID = #{spaceId}
 WHERE PARKING_USAGE_ID = #{usageId} AND EXIT_AT IS NULL

UPDATE PARKING_USAGE u SET PARKING_SPACE_ID = #{spaceId}, PARKING_RESERVATION_ID = #{reservationId}
 WHERE u.PARKING_USAGE_ID = #{usageId} AND u.EXIT_AT IS NULL AND u.VEHICLE_NUMBER = #{number}
   AND u.ENTRY_AT <= #{eventTime}
   AND (u.PARKING_SPACE_ID IS NULL OR u.PARKING_SPACE_ID = #{spaceId})
   AND (u.PARKING_RESERVATION_ID IS NULL OR u.PARKING_RESERVATION_ID = #{reservationId})
   AND 1 = (SELECT COUNT(*) FROM PARKING_USAGE active
             WHERE active.VEHICLE_NUMBER = #{number} AND active.EXIT_AT IS NULL)
   AND EXISTS (SELECT 1 FROM PARKING_RESERVATION r
                WHERE r.PARKING_RESERVATION_ID = #{reservationId}
                  AND r.PARKING_SPACE_ID = #{spaceId} AND r.VEHICLE_NUMBER = #{number}
                  AND r.STATUS_CODE = 'CONFIRMED' AND r.CANCELLED_AT IS NULL
                  AND r.RESERVATION_START_AT <= #{eventTime} AND r.RESERVATION_END_AT >= #{eventTime})
   AND 1 = (SELECT COUNT(*) FROM PARKING_RESERVATION r
             WHERE r.STATUS_CODE = 'CONFIRMED' AND r.CANCELLED_AT IS NULL
               AND r.RESERVATION_START_AT <= #{eventTime} AND r.RESERVATION_END_AT >= #{eventTime}
               AND (r.VEHICLE_NUMBER = #{number} OR r.PARKING_SPACE_ID = #{spaceId}))

UPDATE PARKING_USAGE SET PARKING_SPACE_ID = NULL, PARKING_RESERVATION_ID = NULL
 WHERE PARKING_USAGE_ID = #{usageId} AND PARKING_SPACE_ID = #{spaceId}
   AND VEHICLE_NUMBER = #{number} AND EXIT_AT IS NULL AND LINK_VERSION = #{linkVersion}
